notify = function(title, message, force)
    record(title .. ": " .. message)
    if not alive or (not state.notifications and not force) then
        return
    end
    toastSerial = toastSerial + 1
    local toast = make("Frame", {
        Size = UDim2.new(1, 0, 0, 76),
        BorderSizePixel = 0,
        LayoutOrder = toastSerial,
    }, toastHost)
    bind(toast, "BackgroundColor3", "panel")
    corner(toast, 12)
    stroke(toast, "border")
    local edge = make("Frame", {
        Position = UDim2.fromOffset(0, 14),
        Size = UDim2.fromOffset(3, 48),
        BorderSizePixel = 0,
    }, toast)
    bind(edge, "BackgroundColor3", "accent")
    corner(edge, 2)
    label(toast, title, 12, "text", {
        Position = UDim2.fromOffset(16, 12),
        Size = UDim2.new(1, -29, 0, 18),
        Font = Enum.Font.GothamMedium,
    })
    label(toast, message, 11, "muted", {
        Position = UDim2.fromOffset(16, 33),
        Size = UDim2.new(1, -29, 0, 31),
        TextWrapped = true,
        TextYAlignment = Enum.TextYAlignment.Top,
    })
    local children = {}
    for _, child in ipairs(toastHost:GetChildren()) do
        if child:IsA("Frame") then
            children[#children + 1] = child
        end
    end
    if #children > 3 then
        children[1]:Destroy()
    end
    task.delay(4, function()
        if toast.Parent then
            toast:Destroy()
        end
    end)
end

local function refreshSearch()
    local query = string.lower(searchBox.Text)
    for _, entry in ipairs(searchEntries) do
        if entry.object.Parent then
            entry.object.Visible = query == "" or string.find(entry.text, query, 1, true) ~= nil
        end
    end
end
connect(searchBox:GetPropertyChangedSignal("Text"), refreshSearch)

local function searchable(object, text)
    searchEntries[#searchEntries + 1] = {object = object, text = string.lower(text)}
end

local function createPage(name, glyph, subtitle)
    local scroll = make("ScrollingFrame", {
        Name = name,
        Size = UDim2.fromScale(1, 1),
        BackgroundTransparency = 1,
        BorderSizePixel = 0,
        ScrollBarThickness = 3,
        CanvasSize = UDim2.new(),
        AutomaticCanvasSize = Enum.AutomaticSize.Y,
        ScrollingDirection = Enum.ScrollingDirection.Y,
        Visible = false,
    }, content)
    bind(scroll, "ScrollBarImageColor3", "border")
    pad(scroll, 1, 1, 9, 14)
    make("UIListLayout", {Padding = UDim.new(0, 10), SortOrder = Enum.SortOrder.LayoutOrder}, scroll)
    pages[name] = {frame = scroll, subtitle = subtitle}
    local nav = button(navList, "", {
        Size = UDim2.new(1, 0, 0, 41),
        BackgroundTransparency = 1,
        LayoutOrder = #navButtons + 1,
    })
    local indicator = make("Frame", {
        Position = UDim2.fromOffset(0, 11),
        Size = UDim2.fromOffset(3, 19),
        BorderSizePixel = 0,
        Visible = false,
    }, nav)
    bind(indicator, "BackgroundColor3", "accent")
    corner(indicator, 2)
    local icon = label(nav, glyph, 15, "muted", {
        Position = UDim2.fromOffset(15, 0),
        Size = UDim2.fromOffset(25, 41),
        Font = Enum.Font.Code,
    })
    local text = label(nav, name, 12, "muted", {
        Position = UDim2.fromOffset(48, 0),
        Size = UDim2.new(1, -55, 1, 0),
        Font = Enum.Font.GothamMedium,
    })
    navButtons[#navButtons + 1] = {name = name, button = nav, text = text, icon = icon, indicator = indicator}
    connect(nav.Activated, function()
        selectPage(name)
    end)
    return scroll
end

local function refreshNavigation()
    for _, entry in ipairs(navButtons) do
        local selected = entry.name == activePage
        entry.button.BackgroundColor3 = currentTheme.elevated
        entry.button.BackgroundTransparency = selected and 0 or 1
        entry.text.TextColor3 = selected and currentTheme.text or currentTheme.muted
        entry.icon.TextColor3 = selected and currentTheme.accent or currentTheme.muted
        entry.indicator.Visible = selected
    end
end

selectPage = function(name)
    if not pages[name] then
        return
    end
    activePage = name
    for pageName, page in pairs(pages) do
        page.frame.Visible = pageName == name
    end
    pageTitle.Text = name
    breadcrumb.Text = "WORKSPACE  /  " .. string.upper(name)
    searchBox.Text = ""
    searchBox.PlaceholderText = "Search " .. string.lower(name) .. " controls..."
    refreshSearch()
    refreshNavigation()
end

