    }, accent)
    connect(control.Activated, function()
        invoke(callback)
    end)
    return holder
end

local function choice(parent, title, description, key, options, callback)
    local holder = row(parent, title, description)
    local control = button(holder, "", {
        Position = UDim2.new(1, -162, 0, 18),
        Size = UDim2.fromOffset(144, 33),
    })
    local function refresh()
        control.Text = tostring(state[key]) .. "  >"
    end
    local function set(value, silent)
        if not table.find(options, value) then
            return
        end
        state[key] = value
        refresh()
        if not silent then
            invoke(callback, value)
        end
    end
    connect(control.Activated, function()
        local index = table.find(options, state[key]) or 1
        set(options[index % #options + 1])
    end)
    controls[key] = {set = set, refresh = refresh, kind = "string"}
    refresh()
    return holder
end

local function textInput(parent, title, placeholder, height)
    local holder = make("Frame", {
        Size = UDim2.new(1, 0, 0, height or 150),
        BorderSizePixel = 0,
    }, parent)
    bind(holder, "BackgroundColor3", "panel")
    corner(holder, 10)
    label(holder, title, 12, "text", {
        Position = UDim2.fromOffset(16, 10),
        Font = Enum.Font.GothamMedium,
    })
    local box = make("TextBox", {
        Position = UDim2.fromOffset(16, 40),
        Size = UDim2.new(1, -32, 1, -55),
        BorderSizePixel = 0,
        Text = "",
        PlaceholderText = placeholder,
        TextSize = 11,
        Font = Enum.Font.Code,
        TextWrapped = true,
        TextXAlignment = Enum.TextXAlignment.Left,
        TextYAlignment = Enum.TextYAlignment.Top,
        ClearTextOnFocus = false,
        MultiLine = true,
    }, holder)
    bind(box, "BackgroundColor3", "background")
    bind(box, "TextColor3", "text")
    bind(box, "PlaceholderColor3", "muted")
    corner(box, 7)
    pad(box, 10, 9)
    searchable(holder, title)
    return box
end

