applyTheme = function()
    currentTheme = table.clone(themes[state.theme] or themes.Ocean)
    if accentColors[state.accentChoice] then
        currentTheme.accent = accentColors[state.accentChoice]
    end
    local retained = {}
    for _, entry in ipairs(bindings) do
        if entry.object.Parent then
            entry.object[entry.property] = currentTheme[entry.token]
            retained[#retained + 1] = entry
        end
    end
    bindings = retained
    for _, control in pairs(controls) do
        control.refresh()
    end
    refreshNavigation()
end

local function resize()
    local camera = workspace.CurrentCamera
    local viewport = camera and camera.ViewportSize or Vector2.new(1280, 720)
    local fit = math.min((viewport.X - 28) / 900, (viewport.Y - 46) / 600, 1.12)
    windowScale.Scale = math.max(0.1, fit * (state.compact and 0.88 or 1))
    toastHost.Size = UDim2.fromOffset(math.min(310, math.max(180, viewport.X - 32)), 300)
end

