section(settingsPage, "Configuration", "Export and import JSON manually. No filesystem APIs required.")
local configBox = textInput(settingsPage, "Configuration JSON", "Export a configuration, or paste one here to import.", 200)
local function exportConfig()
    local values = {}
    for key in pairs(controls) do
        values[key] = state[key]
    end
    configBox.Text = HttpService:JSONEncode({version = 1, values = values, notes = notes.Text})
    notify("Configuration exported", "Select and copy the JSON from the text field.")
end
local function importConfig()
    local success, result = pcall(function()
        return HttpService:JSONDecode(configBox.Text)
    end)
    if not success or type(result) ~= "table" or result.version ~= 1 or type(result.values) ~= "table" then
        notify("Invalid configuration", "Paste an ORBIT version 1 JSON export.")
        return
    end
    local applied = 0
    for key, control in pairs(controls) do
        local value = result.values[key]
        if type(value) == control.kind then
            control.set(value, true)
            applied = applied + 1
        end
    end
    if type(result.notes) == "string" then
        notes.Text = string.sub(result.notes, 1, 10000)
    end
    applyTheme()
    applyMovement()
    applyCamera()
    applyLighting()
    updateCrosshair()
    hud.Visible = state.showStats
    coordinatesHud.Visible = state.showCoordinates
    resize()
    notify("Configuration imported", tostring(applied) .. " recognized settings processed.", true)
end
action(settingsPage, "Export configuration", "Write your current settings into the JSON field.", "Export JSON", exportConfig, true)
action(settingsPage, "Import configuration", "Apply the recognized settings from the JSON field.", "Import JSON", importConfig)
action(settingsPage, "Reset preferences", "Restore all controls to their startup settings.", "Reset all", function()
    for key, control in pairs(controls) do
        control.set(defaults[key], true)
    end
    applyTheme()
    applyMovement()
    applyCamera()
    applyLighting()
    updateCrosshair()
    hud.Visible = state.showStats
    coordinatesHud.Visible = state.showCoordinates
    resize()
    notify("Preferences reset", "All controls are back to their startup values.", true)
end)
section(settingsPage, "Session lifecycle")

local function cleanup()
    if not alive then
        return
    end
    alive = false
    for _, connection in ipairs(connections) do
        connection:Disconnect()
    end
    table.clear(connections)
    for _, callback in ipairs(cleanups) do
        pcall(callback)
    end
    for value, original in pairs(originalHumanoids) do
        if value.Parent then
            pcall(function()
                value.WalkSpeed = original.WalkSpeed
                value.JumpPower = original.JumpPower
                value.JumpHeight = original.JumpHeight
            end)
        end
    end
    for camera, fov in pairs(originalCameras) do
        if camera.Parent then
            pcall(function()
                camera.FieldOfView = fov
            end)
        end
    end
    if state.customLighting then
        for property, value in pairs(originalLighting) do
            pcall(function()
                Lighting[property] = value
            end)
        end
    end
    if screen.Parent then
        screen:Destroy()
    end
end

action(settingsPage, "Unload ORBIT", "Restore modified values and disconnect every listener.", "Unload hub", cleanup)
connect(shutdown.Event, cleanup)
